update public.businesses b
set business_template_snapshot=jsonb_build_object(
 'template_id',t.id,'group_id',t.group_id,'group_label',t.group_label,
 'category_label',t.category_label,'template_version',1,
 'configuration',t.configuration,'applied_at',now(),
 'migration_note','Category template refreshed from the approved blueprint; operational records were not changed.'
),updated_at=now()
from public.business_category_templates t
where b.business_category_template_id=t.id
and b.business_category_template_id in ('01-supermarket','03-hair-salon');
